import json
import re

from config import OLLAMA_MODEL
from graph.state import AssistantState
from services.ollama_service import OllamaError, generate_response


DEMO_RESPONSE = (
    "DEMO MODE: This is a fixed sample response, not generated by an AI model. "
    "MediMind can show general educational material from its local reference set, "
    "but this sample is not a personalized assessment. Please discuss health concerns "
    "with a qualified healthcare professional."
)
UNSAFE_RESPONSE_PATTERNS = (
    re.compile(r"\b(?:you (?:may |might |probably |likely |definitely )?have|you are diagnosed with|this confirms)\s+[a-z]", re.IGNORECASE),
    re.compile(
        r"\b(?:take|use|start|stop|increase|decrease|change|prescribe|give)\b.{0,80}"
        r"\b(?:\d+(?:\.\d+)?|one|two|three|four)\s*(?:mg|mcg|μg|g|ml|mL|tablets?|capsules?)\b",
        re.IGNORECASE | re.DOTALL,
    ),
    re.compile(r"\b(?:increase|decrease|change|stop|start)\s+(?:your\s+)?(?:dose|medication|medicine|prescription)\b", re.IGNORECASE),
)


def _unsafe_generated_text(answer: str) -> bool:
    return any(pattern.search(answer) for pattern in UNSAFE_RESPONSE_PATTERNS)


def _prompt(state: AssistantState) -> str:
    sources = [
        {
            "title": item["title"],
            "category": item["category"],
            "content": item["text"],
            "source": item["source_name"],
        }
        for item in state["retrieved_documents"]
    ]
    return f"""You are MediMind, an educational health-information assistant in a college prototype.
Never diagnose, prescribe, recommend a dosage, or recommend changing medication. Use plain language,
state uncertainty, and encourage a qualified clinician for personal concerns. For possible emergencies,
tell the user to contact local emergency services. Do not invent patient history or medical facts.
Use the local reference snippets when relevant. If they do not answer the question, say so. Mention
the titles of references used, but do not invent citations.

Patient context (may be incomplete):
{json.dumps(state['patient_context'], ensure_ascii=True)}

Local reference snippets:
{json.dumps(sources, ensure_ascii=True)}

User question:
{state['question']}

Write a concise, cautious educational response. Do not present this as a diagnosis."""


def run_medical_response(state: AssistantState) -> dict:
    if state["demo_mode"]:
        return {
            "answer": DEMO_RESPONSE,
            "response_mode": "demo",
            "agent_status": state["agent_status"]
            + [{"agent": "Medical Response Agent", "status": "demo", "detail": "Returned a fixed sample; no model was called."}],
        }

    try:
        answer = generate_response(_prompt(state), model=OLLAMA_MODEL)
        if _unsafe_generated_text(answer):
            return {
                "answer": (
                    "The local model produced wording that could be interpreted as a diagnosis or medication instruction, "
                    "so it was withheld. Please ask a qualified healthcare professional for personal guidance."
                ),
                "response_mode": "guarded",
                "agent_status": state["agent_status"]
                + [{"agent": "Medical Response Agent", "status": "failed", "detail": "Safety filter withheld a diagnostic or medication instruction."}],
            }
        return {
            "answer": answer,
            "response_mode": "ollama",
            "agent_status": state["agent_status"]
            + [{"agent": "Medical Response Agent", "status": "success", "detail": f"Generated locally with Ollama ({OLLAMA_MODEL})."}],
        }
    except OllamaError as exc:
        return {
            "answer": f"No AI response was generated. {exc} Enable the explicitly labelled demo mode to show a fixed sample response.",
            "response_mode": "unavailable",
            "agent_status": state["agent_status"]
            + [{"agent": "Medical Response Agent", "status": "failed", "detail": str(exc)}],
        }